let cutoff = datetime(2026-06-10);
let rangeStart = $__timeFrom();
let rangeEnd = $__timeTo();
let effectiveStart = max_of(rangeStart, cutoff);

let excludedPsp = dynamic(["PagoPA","Ente di Test", "MDC Test"]);

let allowed_tpp =
    TppDataSnapshot
    | where business_name !in~ (excludedPsp)
    | summarize by entity_id;

let tpp_entity_map =
    TppDataSnapshot
    | summarize by tpp_id, entity_id;

let known_origins_valid =
    MessageSnapshot
    | where window_start >= cutoff
    | summarize by origin_id, entity_id
    | where entity_id in (allowed_tpp);

let accettati_pairs_dated =
    MessageSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | summarize window_start = min(window_start) by origin_id, entity_id
    | where entity_id in (allowed_tpp);

let accettati_per_day =
    accettati_pairs_dated
    | summarize Accettati = count() by Day = bin(window_start, 1d);

let scartati_per_day =
    MessageVolumeSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | summarize Scartati = coalesce(sum(message_discarded_count), 0) by Day = bin(window_start, 1d);

let dayRange =
    range Day from startofday(effectiveStart) to startofday(rangeEnd) step 1d
    | project Day;

// Letti: validati contro known_origins_valid (senza upper bound), datati sul proprio window_start
let letti_pairs_dated =
    RetrievalIdVolumeSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | project origin_id, window_start
    | join kind=inner known_origins_valid on origin_id
    | summarize window_start = min(window_start) by origin_id, entity_id;

let letti_per_day =
    letti_pairs_dated
    | summarize Letti = count() by Day = bin(window_start, 1d);

// Perfezionati: entity_id derivato da tpp_id, poi validato su (origin_id, entity_id) — non solo origin_id
let perfezionati_pairs_dated =
    FinalizedMessageSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | join kind=inner tpp_entity_map on tpp_id
    | join kind=inner known_origins_valid on origin_id, entity_id
    | summarize window_start = min(window_start) by origin_id, tpp_id;

let perfezionati_per_day =
    perfezionati_pairs_dated
    | summarize Perfezionati = count() by Day = bin(window_start, 1d);

dayRange
| join kind=leftouter accettati_per_day on Day
| join kind=leftouter scartati_per_day on Day
| join kind=leftouter letti_per_day on Day
| join kind=leftouter perfezionati_per_day on Day
| extend Accettati    = coalesce(Accettati, 0),
         Scartati     = coalesce(Scartati, 0),
         Letti        = coalesce(Letti, 0),
         Perfezionati = coalesce(Perfezionati, 0)
| extend Ricevuti = Scartati + Accettati
| project window_start = Day, Ricevuti, Accettati, Letti, Perfezionati
| order by window_start asc

let cutoff = datetime(2026-06-10);
let rangeStart = $__timeFrom();
let rangeEnd = $__timeTo();
let effectiveStart = max_of(rangeStart, cutoff);

let excludedPsp = dynamic(["PagoPA","Ente di Test", "MDC Test"]);

let allowed_tpp =
    TppDataSnapshot
    | where business_name !in~ (excludedPsp)
    | summarize by entity_id;

let tutte_le_tpp =
    TppDataSnapshot
    | where business_name !in~ (excludedPsp)
    | summarize by tpp_id, entity_id, PSP = business_name;

// Universo: coppie (origin_id, entity_id) accettate nel periodo, con relativo flag pagamento (più recente nel periodo)
let accettati_pairs =
    MessageSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | summarize arg_max(window_start, associated_payment) by origin_id, entity_id
    | where entity_id in (allowed_tpp)
    | project origin_id, entity_id, associated_payment;

let known_origins = accettati_pairs | project origin_id, entity_id;

// Letti/Perfezionati/Pagati: derivo l'entity_id canonico via origin_id, MAI dal campo nativo delle altre tabelle
let letti_pairs =
    RetrievalIdVolumeSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | project origin_id
    | join kind=inner known_origins on origin_id
    | summarize by origin_id, entity_id;

let perfezionati_pairs =
    FinalizedMessageSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | join kind=inner tutte_le_tpp on tpp_id
    | join kind=inner known_origins on origin_id
    | summarize by origin_id, entity_id;

let pagati_pairs =
    PaymentAttemptSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | project origin_id
    | join kind=inner known_origins on origin_id
    | summarize by origin_id, entity_id;

let funnel =
    accettati_pairs
    | join kind=leftouter (letti_pairs | extend is_letta = true) on origin_id, entity_id
    | join kind=leftouter (perfezionati_pairs | extend is_perfezionata = true) on origin_id, entity_id
    | join kind=leftouter (pagati_pairs | extend is_pagata = true) on origin_id, entity_id
    | project origin_id, entity_id, associated_payment,
        is_letta = coalesce(is_letta, false),
        is_perfezionata = coalesce(is_perfezionata, false),
        is_pagata = coalesce(is_pagata, false);

tutte_le_tpp
| join kind=leftouter funnel on entity_id
| summarize
    ['Accettati']            = countif(isnotempty(origin_id)),
    ['Letti']                = countif(is_letta),
    ['Perfezionati']         = countif(is_perfezionata),
    ['Perf. Con Pagamento']  = countif(is_perfezionata and associated_payment == true),
    ['Pagati']               = countif(is_pagata and associated_payment == true)
    by PSP
| extend ['Tasso Let. %']   = round(100.0 * ['Letti'] / iff(['Accettati'] == 0, 1, ['Accettati']), 2)
| extend ['Tasso Perf. %']  = round(100.0 * ['Perfezionati'] / iff(['Letti'] == 0, 1, ['Letti']), 2)
| extend ['Tasso di Pag. %']= round(100.0 * ['Pagati'] / iff(['Perf. Con Pagamento'] == 0, 1, ['Perf. Con Pagamento']), 2)
| project PSP, ['Accettati'], ['Letti'], ['Perfezionati'], ['Pagati'], ['Tasso Let. %'], ['Tasso Perf. %'], ['Tasso di Pag. %']
| order by ['Accettati'] desc
